'use strict';
const slides=[{eyebrow:'WELCOME TO TOYOTA FINANCIAL SERVICES',title:'Every journey begins<br>with a next move.',text:'Tools, resources and support to help you move forward with your Toyota.',cta:'Explore your demo account',href:'guardian.html'},{eyebrow:'INTRODUCING SMART SERVICE GUARDIAN',title:'More clarity.<br>Less guesswork.',text:'Understand your service needs, explore local offers and make your next move with confidence.',cta:'Meet your Guardian',href:'guardian.html'},{eyebrow:'TAKE CARE OF WHAT DRIVES YOU',title:'Your Toyota deserves<br>a little peace of mind.',text:'Explore an illustrative service plan personalized to your vehicle and priorities.',cta:'Review my maintenance',href:'guardian.html#maintenance'}];
function renderHomeSlide(i){const s=slides[i];document.getElementById('hero-slide').innerHTML=`<div class="hero-scenery"></div><img class="hero-car" src="assets/vehicle.svg" alt="Illustration of a silver Toyota-style sedan"><div class="hero-content"><div class="eyebrow" style="margin-bottom:17px;font-size:10px">${s.eyebrow}</div><h1>${s.title}</h1><p>${s.text}</p><a class="btn" href="${s.href}">${s.cta} ${icon('arrow')}</a></div><div class="hero-pager" aria-label="Homepage highlights">${slides.map((_,n)=>`<button class="pager-dot ${n===i?'active':''}" data-slide="${n}" aria-label="Show highlight ${n+1}" aria-pressed="${n===i}"></button>`).join('')}</div>`;}
document.getElementById('home').innerHTML=`<div class="notice">${icon('info')} A new way to care for your Toyota. Explore Smart Service Guardian in your demo account. <a class="text-link" style="margin-left:auto;font-size:10px;white-space:nowrap" href="guardian.html">Take a look ${icon('arrow')}</a></div><section class="home-hero" id="hero-slide" aria-label="Toyota Financial Services highlights"></section><div class="home-main"><section class="home-actions" aria-label="Quick links"><a class="home-action" href="guardian.html">${icon('user')}<h3>Manage your account</h3><p>A clear view of your Toyota and your next step.</p><span class="text-link">Open demo account ${icon('arrow')}</span></a><a class="home-action" href="guardian.html#local">${icon('tag')}<h3>Explore local offers</h3><p>Service options for the road ahead.</p><span class="text-link">Discover offers ${icon('arrow')}</span></a><a class="home-action" href="guardian.html#maintenance">${icon('shield')}<h3>Care for your Toyota</h3><p>Make sense of your service needs and protection.</p><span class="text-link">View maintenance ${icon('arrow')}</span></a><a class="home-action" href="guardian.html#compare">${icon('car')}<h3>Plan your next move</h3><p>Understand the cost of keeping or upgrading.</p><span class="text-link">Compare options ${icon('arrow')}</span></a></section><section class="guardian-promo"><div class="promo-copy"><div class="eyebrow red">NEW · SMART SERVICE GUARDIAN</div><h2>Your next service decision.<br>A little smarter.</h2><p>Know what your Toyota needs, what you may pay and whether keeping it makes sense for you.</p><a class="btn" href="guardian.html">Explore Smart Service Guardian ${icon('arrow')}</a></div><div class="promo-visual"><img src="assets/vehicle.svg" alt="Silver sedan illustration"><div class="promo-float"><span class="check-circle">✓</span><div><strong>Your Toyota, understood.</strong><br><span style="color:#888;font-size:9px">Personalized care. Clearer choices.</span></div></div></div></section><section class="question-band"><h2>A little guidance goes a long way.</h2><p class="muted" style="font-size:12px;margin-bottom:17px">Start with your Toyota. Explore the possibilities.</p><a class="text-link" href="guardian.html">Visit your Smart Service Guardian ${icon('arrow')}</a></section></div>`;renderHomeSlide(0);document.addEventListener('click',e=>{const b=e.target.closest('[data-slide]');if(b)renderHomeSlide(Number(b.dataset.slide));});
if(location.hash==='#account')modal('Welcome to your demo account',`<p>Explore a synthetic Toyota customer account. No sign-in or real credentials are required.</p><a class="btn" href="guardian.html">Continue as Alex ${icon('arrow')}</a>`);
